/**
 * Enriches content/manifest.json trading cards with `ratingValue`, read from
 * each post's reviewJsonLd (generated by scripts/gen-review-schema.mjs).
 *
 * Run from the next-app/ directory:  node scripts/enrich-manifest-rating.mjs
 *
 * This only surfaces the existing review rating onto listing cards — it does
 * not create or change any score.
 */
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';

const ratingBySlug = new Map();
const dir = 'content/posts/trading';
for (const f of readdirSync(dir)) {
  if (!f.endsWith('.json')) continue;
  const slug = f.replace(/\.json$/, '');
  try {
    const p = JSON.parse(readFileSync(`${dir}/${f}`, 'utf8'));
    const rl = p.reviewJsonLd ? JSON.parse(p.reviewJsonLd) : null;
    const graph = rl ? rl['@graph'] || rl : null;
    const review = Array.isArray(graph)
      ? graph.find((x) => x['@type'] === 'Review')
      : graph;
    const r = review && review.reviewRating ? review.reviewRating.ratingValue : undefined;
    if (r) ratingBySlug.set(slug, r);
  } catch {
    // skip unreadable post
  }
}

const manifestPath = 'content/manifest.json';
const m = JSON.parse(readFileSync(manifestPath, 'utf8'));

let rated = 0;
const enrich = (cards) => {
  for (const card of cards) {
    if (card.type !== 'trading') continue;
    const r = ratingBySlug.get(card.slug);
    if (r) {
      card.ratingValue = r;
      rated++;
    }
  }
};

for (const page of m.homePages) enrich(page);
for (const a of Object.values(m.authors)) for (const page of a.pages) enrich(page);

writeFileSync(manifestPath, JSON.stringify(m));
console.log(`enriched ${rated} trading cards with ratingValue`);
